    }

    /// The record's fields alone, as a platform sends it back.
    var seed: Seed {
        Seed(
            kind: kind,
            title: title,
            subtitle: subtitle,
            symbol: symbol,
            subjectID: subjectID,
            tabID: tabID,
            address: address,
            command: command,
            provider: provider?.seed,
            settingsPage: settingsPage,
            scope: scope,
            reason: reason
        )
    }
}

